// Descriptors of the recompiled modules, generated by tools/gen_glue.py into aot_modules.cpp.
#pragma once
#include <cstddef>
#include <cstdint>
#include "table.h"

struct AotModuleDesc {
    const char* name;       // exefs file name: rtld, main, subsdk0, sdk, ...
    const char* module_id;  // NSO build id (hex) the code was recompiled from
    uint64_t* base;         // load base variable read by the generated code (MB)
    const FnEntry* table;   // module-relative function table, sorted (size: aot_table_size)
    uint64_t image_size;    // text + ro + data + bss, page aligned
};

extern const AotModuleDesc g_aot_modules[];
extern const size_t g_aot_module_count;
size_t aot_table_size(size_t i);
